"""Shared readable form/table treatment for new workflow pages."""
PAGE_STYLE='QWidget{background:#f3f6fa;color:#263b51;} QLabel{background:transparent;} QPushButton{background:white;color:#285580;border:1px solid #cbd7e6;border-radius:6px;padding:8px 10px;} QPushButton:hover{background:#edf4ff;} QPushButton:disabled{color:#7c8da0;background:#edf0f4;} QComboBox,QLineEdit,QDoubleSpinBox{background:white;color:#263b51;border:1px solid #cbd7e6;border-radius:5px;padding:5px;} QTableWidget,QPlainTextEdit{background:white;color:#263b51;border:1px solid #d5dfeb;gridline-color:#e3eaf2;} QHeaderView::section{background:#edf3fa;color:#36506b;padding:6px;border:0;} QCheckBox::indicator{width:15px;height:15px;background:white;border:1px solid #8a9db2;border-radius:3px;} QCheckBox::indicator:checked{background:#2563ad;border-color:#2563ad;}'
